patch:
--- web/src/lib/industry-renderer.ts
+++ web/src/lib/industry-renderer.ts
@@ -58,14 +58,26 @@
     } else {
       listTop = h * 0.34;
     }

-    const menuPoints = allPoints.slice(0, 6);
-    const slotH = (h * 0.78 - listTop) / Math.max(1, menuPoints.length);
+    const lang = state.outputLanguage;
+    const ratio = h / w;
+    const maxVisible = ratio < 1.1 ? 3 : (ratio < 1.4 ? 4 : 5);
+    const showCue = allPoints.length > maxVisible;
+    const displayCount = showCue ? maxVisible : allPoints.length;
+    const menuPoints = allPoints.slice(0, displayCount);
+    const totalSlots = displayCount + (showCue ? 1 : 0);
+    
+    const maxAvailH = h * 0.82 - listTop;
+    const rawSlotH = totalSlots > 0 ? maxAvailH / totalSlots : maxAvailH;
+    const isSparse = allPoints.length <= 2;
+    const slotH = Math.min(rawSlotH, isSparse ? h * 0.12 : h * 0.09);
+    const fontSize = w * (isSparse ? 0.05 : 0.038);
+    
     menuPoints.forEach((p, i) => {
       const py = listTop + i * slotH;
       if (i > 0) { ctx.fillStyle = 'rgba(38,58,44,0.15)'; ctx.fillRect(inset * 2, py, w - inset * 4, 1); }
-      drawText(p, inset * 2, py + slotH * 0.1, w - inset * 4, slotH * 0.8, w * 0.04, paperInk, '500');
+      drawText(p, inset * 2, py + slotH * 0.1, w - inset * 4, slotH * 0.8, fontSize, paperInk, '500');
     });

-    const lang = state.outputLanguage;
+    let nextY = listTop + displayCount * slotH;
+    
+    if (showCue) {
+      const cueText = lang === 'en' ? `+ ${allPoints.length - maxVisible} MORE IN DETAILS` : `+ ${allPoints.length - maxVisible} MÓN KHÁC Ở CHI TIẾT`;
+      ctx.fillStyle = 'rgba(38,58,44,0.15)'; ctx.fillRect(inset * 2, nextY, w - inset * 4, 1);
+      drawText(cueText, inset * 2, nextY + slotH * 0.1, w - inset * 4, slotH * 0.8, w * 0.035, paperRust, '700');
+      nextY += slotH;
+    }
+    
     const contact = fields.contact || fields.booking || '';
     const ctaText = copy.cta || (lang === 'en' ? 'VIEW MENU' : 'XEM THỰC ĐƠN');
-    drawText(ctaText, inset * 2, h * 0.85, w - inset * 4, h * 0.04, w * 0.04, paperRust, '800');
-    drawText(contact, inset * 2, h * 0.90, w - inset * 4, h * 0.04, w * 0.035, paperInk, '500');
+    const ctaY = isSparse ? nextY + h * 0.04 : Math.max(nextY + h * 0.02, h * 0.82);
+    
+    drawText(ctaText, inset * 2, ctaY, w - inset * 4, h * 0.04, w * 0.04, paperRust, '800');
+    if (contact) {
+      drawText(contact, inset * 2, ctaY + h * 0.045, w - inset * 4, h * 0.04, w * 0.035, paperInk, '500');
+    }

     return true;
   }
